#!/usr/bin/env python3
"""Regenerates binders/docs/RULES.md from the card data. Run: python3 binders/tools/gen_rules_doc.py"""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
data = root / "core" / "Binders.Core" / "Data"
C = json.loads((data / "cards.json").read_text(encoding="utf-8"))
D = json.loads((data / "decks.json").read_text(encoding="utf-8"))
fac = {"Flame": "🔥 لهب", "Tide": "🌊 نهر", "Stone": "🪨 حجر", "Storm": "⚡ عاصفة", "Shadow": "🌑 ظل", "None": "محايد"}
typ = {"Creature": "وحش", "Spell": "سحر", "Trap": "فخ", "Field": "ساحة"}
rows = []
for t in ["Creature", "Spell", "Trap", "Field"]:
    for c in sorted((c for c in C if c["Type"] == t), key=lambda c: (c["Cost"], c["Id"])):
        st = f"{c['Attack']} / {c['Defense']}" if t == "Creature" else ""
        rows.append(f"| **{c['NameAr']}** | {typ[t]} | {fac[c['Faction']]} | {c['Cost']} | {st} | {c['TextAr']} | `{c['Id']}` |")
names = {c["Id"]: c["NameAr"] for c in C}
decks = [f"- **{d['NameAr']}** (`{d['Id']}`): " + ", ".join(f"{names[k]} ×{v}" for k, v in d["Cards"].items()) for d in D]
HEAD = '# قواعد BINDERS: ختم الأرواح\n\n> الملف ده بيتولّد من `core/Binders.Core/Data/*.json`. عدّل الكروت هناك، والقيم هنا مجرد نسخة للقراءة.\n\n## الفكرة\nكل لاعب معاه ديك 30 كارت. الهدف إنك تنزّل نقاط حياة الخصم من **4000** لـ **صفر**.\n\n## الدور\n1. **بداية الدور:** طاقتك القصوى تزيد 1 (لحد 10) وتتملي. بعدين تسحب كارت.\n   اللي بيبدأ الماتش مبيسحبش في أول دور، ومحدش يقدر يهاجم في أول دور في الماتش.\n2. **اللعب:** تنزّل كروت بتكلفتها من الطاقة، بأي ترتيب.\n3. **المعركة:** كل وحش في وضع الهجوم يقدر يهاجم مرة واحدة.\n4. **إنهاء الدور.**\n\n## الساحة\n- **3 خانات وحوش** و**3 خانات فخاخ** لكل لاعب.\n- **كارت ساحة واحد للترابيزة كلها:** بيأثّر على وحوش الاتنين، وأي كارت ساحة جديد بيشيل القديم.\n\n## الوحوش\n- تنزل في **وضع الهجوم** أو **وضع الدفاع**.\n- الوحش الجديد مبيهاجمش في نفس الدور، إلا لو عنده **سرعة (Haste)**.\n- تقدر تغيّر وضع الوحش مرة في الدور، بس مش بعد ما يهاجم.\n- الوحش اللي في وضع الدفاع مبيهاجمش.\n\n## حساب المعركة\n| الحالة | النتيجة |\n|---|---|\n| هجوم ضد هجوم، المهاجم أقوى | المدافع يتدمّر، وصاحبه يخسر الفرق |\n| هجوم ضد هجوم، المهاجم أضعف | المهاجم يتدمّر، وصاحبه يخسر الفرق |\n| هجوم ضد هجوم، متساويين | الاتنين يتدمّروا، ومحدش يخسر حياة |\n| هجوم ضد دفاع، الهجوم أكبر | المدافع يتدمّر، ومحدش يخسر حياة |\n| هجوم ضد دفاع، الهجوم أصغر | صاحب المهاجم يخسر الفرق |\n| هجوم مباشر | مسموح بس لو الخصم مفيش عنده وحوش ينفع تتهاجم |\n\n## الفخاخ\nبتتحط مقلوبة وبتدفع تكلفتها وقت ما تحطها. بتشتغل **لوحدها** لما الخصم يهاجم، أول فخ مناسب بس في كل هجمة.\n\n## حالات خاصة\n- **إيد مليانة (8 كروت):** الكارت المسحوب يروح المقبرة على طول.\n- **الديك خلص:** كل مرة تحاول تسحب تخسر 500 نقطة.\n- **التجميد:** الوحش المتجمد مبيهاجمش ومبيغيّرش وضعه لحد آخر دور صاحبه الجاي.\n\n## الأوامر الصوتية\nالصيغة: **[اسم الوحش] + [الأمر] + [الهدف]**\n- «يا سعير، اهجم على أبو الهول»\n- «يا سعير، تحول إلى وضعية الدفاع»\n- «انهي الدور»\n\nلو في وحش واحد بس يقدر يهاجم، أو هدف واحد بس، تقدر تقول «اهجم» بس. وفيه أسماء مختصرة لكل وحش (موجودة في `Aliases`).\n'
doc = (HEAD + f"\n## الكروت ({len(C)} كارت)\n| الاسم | النوع | الفصيل | التكلفة | هجوم / دفاع | القدرة | المعرّف |\n|---|---|---|---|---|---|---|\n"
       + "\n".join(rows) + "\n\n## الديكات المبدئية\n" + "\n".join(decks) + "\n")
(root / "docs" / "RULES.md").write_text(doc, encoding="utf-8")
print("Wrote", root / "docs" / "RULES.md")
